  private int parse(final int from) {
    char c;
    numEscapes = 0;
    for (int i = from; ; i++) {
      if (i >= tail) {
        throw reportError("parse", "incomplete string");
      }
      c = peekChar(i);
      if (c == '"') {
        head = i + 1;
        return i - from;
      } else if (c == '\\') {
        ++numEscapes;
        ++i;
      }
    }
  }

// CharsJsonIterator lines 116-119
